import*as THREE from'three';import{Button}from'../../core/index.js';import{spec}from'./dimensions.js';
/** Exact own front-shell RESET tongue;all3194 faces and native indices kept. */
export class NativeReset extends Button{
 constructor({shell,follower}){const proxy=new THREE.Mesh(new THREE.PlaneGeometry(3.3,3.0).rotateY(-Math.PI/2),new THREE.MeshBasicMaterial({transparent:true,opacity:0,depthWrite:false}));proxy.name='M5Camera-X own native RESET cap input proxy';super({id:'reset',label:'M5Camera-X actual side RESET cap',mesh:proxy,position:spec.reset.position,axis:spec.reset.axis,travel:spec.reset.travelMm,meta:{role:'actual-native-reset-cap',scope:'Physical momentary intent/native cap flexure only;no reboot,power or firmware',travelSource:'Own native tongue/hinge and exact own03 photograph;0.18mm inferred visual free-edge travel'}});this.shell=shell;this.follower=follower;this.followerRest=follower.position.clone();this.rest=shell.geometry.attributes.position.array.slice();this.norm=shell.geometry.attributes.normal.array.slice();this.weights=new Float32Array(this.rest.length/3);this.slopes=new Float32Array(this.weights.length);this.affectedIndices=[];this.lastDepth=0;this.followerWeight=this.weightAtZ(follower.position.z);
  for(let i=0;i<this.weights.length;i++){const k=i*3,x=this.rest[k],y=this.rest[k+1],z=this.rest[k+2],m=spec.reset.mask;if(x>m.xMax||y<m.yRange[0]||y>m.yRange[1]||z<m.zRange[0]||z>=m.zRange[1])continue;const t=THREE.MathUtils.clamp((spec.reset.hingeZ-z)/(spec.reset.hingeZ-spec.reset.freeZ),0,1);this.weights[i]=t*t*(3-2*t);this.slopes[i]=-6*t*(1-t)/(spec.reset.hingeZ-spec.reset.freeZ);if(this.weights[i]>0)this.affectedIndices.push(i);}this.meta.deformedNativeVertices=this.affectedIndices.length;
 }
 weightAtZ(z){const t=THREE.MathUtils.clamp((spec.reset.hingeZ-z)/(spec.reset.hingeZ-spec.reset.freeZ),0,1);return t*t*(3-2*t);}
 update(dt){const changed=super.update(dt),depth=this.getActuationState().depthMm;if(depth===this.lastDepth)return changed;const p=this.shell.geometry.attributes.position,n=this.shell.geometry.attributes.normal;for(const i of this.affectedIndices){const k=i*3;p.setXYZ(i,this.rest[k]+depth*this.weights[i],this.rest[k+1],this.rest[k+2]);if(depth){let x=this.norm[k],y=this.norm[k+1],z=this.norm[k+2]-depth*this.slopes[i]*x,l=Math.hypot(x,y,z);n.setXYZ(i,x/l,y/l,z/l);}else n.setXYZ(i,this.norm[k],this.norm[k+1],this.norm[k+2]);}p.needsUpdate=true;n.needsUpdate=true;this.shell.geometry.computeBoundingBox();this.shell.geometry.computeBoundingSphere();this.follower.position.copy(this.followerRest);this.follower.position.x+=depth*this.followerWeight;this.lastDepth=depth;return true;}
 dispose(){super.dispose();this.shell=null;this.follower=null;this.rest=null;this.norm=null;this.weights=null;this.slopes=null;this.affectedIndices=null;}
}
